import { Link } from 'react-router-dom';

const Home = () => {
  return (
    <div className="home">
      <h1>Welcome to the Cyber Awareness Toolkit 🇧🇭</h1>
      <p>Explore tools designed to help you stay safe online:</p>

      <div className="tool-links">
        <Link to="/chatbot">
          <button>Cyber Awareness Chatbot</button>
        </Link>

        <Link to="/password-checker">
          <button>🔐 Password Strength Checker</button>
        </Link>
      </div>
    </div>
  );
};

export default Home;
